mapper.select:
SELECT COUNT(DISTINCT CAST(SALES_ORDER AS UNSIGNED))
FROM BASIL_SBX_PRD.RAW_SYSPRO_INPUT


        CAST(SALES_ORDER AS UNSIGNED) = #{salesOrder}



        AND CUSTOMER_PO_NUMBER = #{poNumber}



        AND CAST(CUSTOMER AS UNSIGNED) = #{customerId}


        AND REQ_SHIP_DATE BETWEEN #{shipFromDate} AND #{shipToDate}



        AND ORDER_DATE BETWEEN #{createFromDate} AND #{createToDate}

SELECT DISTINCT CAST(SALES_ORDER AS UNSIGNED) AS salesOrder, mc.CUSTOMER_ORGANIZATION AS customer, scav.VALUE AS orderStatus, ORDER_DATE AS orderDate, CUSTOMER_PO_NUMBER AS customerPONumber, MO_DESCRIPTION AS description, SPECIAL_INSTRUCTIONS AS specialInstructions, SALES_PERSON_NAME AS salesPerson, CONTACT AS contact, CUSTOMER_NAME AS sysproCustomerName, CONCAT(`SHIP_ADDRESS_1`, ' ', `SHIP_ADDRESS_2`, '\n', `SHIP_ADDRESS_3`, ' ', `SHIP_ADDRESS_4`, ', ', `SHIP_POSTAL_CODE`) AS shipAddress, REQ_SHIP_DATE AS reqShipDate FROM BASIL_SBX_PRD.RAW_SYSPRO_INPUT rsi LEFT JOIN BASIL_ODS_PRD.MASTER_CUSTOMER mc ON CAST(rsi.CUSTOMER AS UNSIGNED) = mc.MC_OID LEFT JOIN BASIL_SEC_PRD.SUPPORT_CLIENT_ATTRIBUTE_VALUES scav ON scav.SYSPRO_CODE = rsi.ORDER_STATUS AND SC_OID = 3
CAST(SALES_ORDER AS UNSIGNED) = #{salesOrder}
AND CUSTOMER_PO_NUMBER = #{poNumber}
AND CAST(CUSTOMER AS UNSIGNED) = #{customerId}
AND REQ_SHIP_DATE BETWEEN #{shipFromDate} AND #{shipToDate}
AND ORDER_DATE BETWEEN #{createFromDate} AND #{createToDate}
ORDER BY ${sortColumns}
LIMIT #{offset,jdbcType=INTEGER},#{count,jdbcType=INTEGER}
